LABS = {"lr3": LR3, "lr4": LR4}


# ---------------------------------------------------------------- построение

def latin_runs(paragraph, text: str, bold: bool = False) -> None:
    """Текст с выделением кода в обратных кавычках без самих кавычек; вся прочая латиница остаётся прямой (курсив ставит report-gen)."""
    for index, piece in enumerate(re.split(r"`([^`]+)`", text)):
        if piece:
            run = paragraph.add_run(piece)
            run.bold = bold or None
            if index % 2 == 1:
                run.italic = True


def line(document, text: str = "", center: bool = False, bold: bool = False, tab_cm: float | None = None):
    paragraph = document.add_paragraph(style="Normal")
    fmt = paragraph.paragraph_format
    fmt.first_line_indent = Cm(0)
    fmt.space_before = Pt(0)
    fmt.space_after = Pt(0)
    fmt.line_spacing_rule = WD_LINE_SPACING.SINGLE
    paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER if center else WD_ALIGN_PARAGRAPH.LEFT
    if tab_cm is not None:
        fmt.tab_stops.add_tab_stop(Cm(tab_cm))
    if text:
        run = paragraph.add_run(text)
        run.bold = bold
    return paragraph


def title_page(document, lab: dict) -> None:
    spec = [
        ("Министерство образования Республики Беларусь", {"center": True}),
        ("", {}),
        ("Учреждение образования", {"center": True}),
        ("БЕЛОРУССКИЙ ГОСУДАРСТВЕННЫЙ УНИВЕРСИТЕТ", {"center": True}),
        ("ИНФОРМАТИКИ И РАДИОЭЛЕКТРОНИКИ", {"center": True}),
        ("", {}),
        (f"Факультет\t{FACULTY}", {"tab_cm": 3.0}),
        ("", {}),
        (f"Кафедра\t{DEPARTMENT}", {"tab_cm": 3.0}),
        *[("", {})] * 7,
        ("ОТЧЕТ", {"center": True}),
        (lab["kind"], {"center": True}),
        ("", {}),
        (lab["topic"], {"center": True, "bold": True}),
        *[("", {})] * 9,
        (f"Выполнила\tст. гр. {GROUP}", {"tab_cm": 11.0}),
        (f"\t{STUDENT}", {"tab_cm": 11.0}),
        ("", {}),
        (f"Проверил\t{TEACHER}", {"tab_cm": 11.0}),
        ("Минск 2026", {"center": True}),
    ]
    for text, options in spec:
        line(document, text, **options)


def body(document, text: str):
    paragraph = document.add_paragraph(style="Normal")
    latin_runs(paragraph, text)
    return paragraph


def figure(document, shots: Path, file: str, caption: str) -> None:
    holder = document.add_paragraph(style="Normal")
    holder.alignment = WD_ALIGN_PARAGRAPH.CENTER
    holder.paragraph_format.first_line_indent = Cm(0)
    holder.add_run().add_picture(str(shots / file), width=Cm(16))
    document.add_paragraph(f"Рисунок {document._figures} – {caption}", style="Caption")


def table(document, number: int, caption: str, header: list[str], rows: list[list[str]]) -> None:
    line_caption = document.add_paragraph(f"Таблица {number} – {caption}", style="Normal")
    line_caption.paragraph_format.first_line_indent = Cm(0)
    line_caption.paragraph_format.keep_with_next = True
    grid = document.add_table(rows=1, cols=len(header))
    grid.style = "Table Grid"
    for cell, text in zip(grid.rows[0].cells, header, strict=True):
        cell.text = text
    for row in rows:
        cells = grid.add_row().cells
        for cell, text in zip(cells, row, strict=True):
            cell.text = text
    document.add_paragraph("", style="Normal")


def listing(document, number: int, title: str, path: Path, pattern: str | None) -> None:
    source = path.read_text(encoding="utf-8")
    if pattern:
        match = re.search(pattern, source, flags=re.DOTALL)
        if not match:
            raise SystemExit(f"в {path} не найден фрагмент {pattern}")
        source = match.group(0)
    document.add_paragraph(f"Листинг {number} – {title}", style="Normal").paragraph_format.first_line_indent = Cm(0)
    for code_line in source.rstrip("\n").split("\n"):
        paragraph = document.add_paragraph(code_line if code_line.strip() else " ", style="Normal")
        paragraph.alignment = WD_ALIGN_PARAGRAPH.LEFT
        paragraph.paragraph_format.first_line_indent = Cm(0)


def build(lab: dict) -> Path:
    document = Document()
    document._figures = 0
    for name in ("Normal", "Heading 1", "Heading 2", "Caption", "List Bullet"):
        font = document.styles[name].font
        font.name = "Times New Roman"
        font.size = Pt(14)
        font.color.rgb = RGBColor(0, 0, 0)
        if name != "Normal":
            font.bold = name.startswith("Heading")
            font.italic = False
        rpr = document.styles[name].element.get_or_add_rPr()
        fonts = rpr.get_or_add_rFonts()
        for attribute in ("w:asciiTheme", "w:hAnsiTheme", "w:eastAsiaTheme", "w:cstheme"):
            fonts.attrib.pop("{http://schemas.openxmlformats.org/wordprocessingml/2006/main}" + attribute.split(":")[1], None)
        fonts.set("{http://schemas.openxmlformats.org/wordprocessingml/2006/main}ascii", "Times New Roman")
        fonts.set("{http://schemas.openxmlformats.org/wordprocessingml/2006/main}hAnsi", "Times New Roman")
    title_page(document, lab)
    document.add_heading("Введение", level=1)
    for text in lab["intro"]:
        body(document, text)
    document.add_heading("1 Постановка задачи", level=1)
    for kind, text in lab["posting"]:
        if kind == "p":
            body(document, text)
        else:
            document.add_paragraph(text, style="List Bullet")
    document.add_heading("2 Теоретическая часть", level=1)
    for text in lab["theory"]:
        body(document, text)
    document.add_heading("3 Ход работы", level=1)
    tables = 0
    for item in lab["work"]:
        kind = item[0]
        if kind == "h":
            document.add_heading(item[1], level=2)
        elif kind == "p":
            body(document, item[1])
        elif kind == "f":
            document._figures += 1
            figure(document, lab["shots"], item[1], item[2])
        elif kind == "t":
            tables += 1
            table(document, tables, item[1], item[2], item[3])
    document.add_heading("4 Ответы на контрольные вопросы", level=1)
    for question, answer in lab["questions"]:
        paragraph = document.add_paragraph(style="Normal")
        latin_runs(paragraph, question, bold=True)
        body(document, answer)
    document.add_heading("Заключение", level=1)
    for text in lab["conclusion"]:
        body(document, text)
    for number, (title, path, pattern) in enumerate(lab["listings"], start=1):
        listing(document, number, title, path, pattern)
    work_dir = ROOT / lab["name"].split("_")[0] / "source"
    work_dir.mkdir(parents=True, exist_ok=True)
    target = work_dir / f"{lab['name']}.docx"
    document.save(str(target))
    return target


def main() -> int:
    lab = LABS[sys.argv[1]]
    target = build(lab)
    output = target.parent.parent / "готово"
    command = [sys.executable, "scripts/finalize_reports.py", str(target.parent), str(output), "--force", "--practice"]
    env = {"PYTHONPATH": "E:/zapiska-gen/src", "REPORTGEN_NONINTERACTIVE": "1"}
    import os

    result = subprocess.run(command, cwd=ZAPISKA, capture_output=True, text=True, encoding="utf-8", errors="replace", env={**os.environ, **env})
    print(result.stdout[-3000:], result.stderr[-1500:])
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
